mapper.select:
select

from agent_enhancer
where 1 = 1

    and (
        agent_enhancer_code like concat('%', #{q.keyword}, '%')
        or agent_enhancer_name like concat('%', #{q.keyword}, '%')
        or agent_enhancer_type like concat('%', #{q.keyword}, '%')
    )


    and enabled = #{q.enabled}


    and agent_enhancer_type = #{q.agentEnhancerType}

order by updated_at desc, id desc
limit #{q.offset}, #{q.pageSize}

select count(1)
from agent_enhancer
where 1 = 1

    and (
        agent_enhancer_code like concat('%', #{q.keyword}, '%')
        or agent_enhancer_name like concat('%', #{q.keyword}, '%')
        or agent_enhancer_type like concat('%', #{q.keyword}, '%')
    )


    and enabled = #{q.enabled}


    and agent_enhancer_type = #{q.agentEnhancerType}

mapper.delete:
delete from agent_enhancer
where 1 = 1
  and id = #{id}
